import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { describe, it } from "node:test";

// App-dir icon files (generated by scripts/generate-brand-icons.mjs from
// public/brand/launchpad-hq-512.png). Parsed by hand: no image dependency.

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const CREATE_NEXT_APP_FAVICON_BYTES = 25931;

/** Width and height from a PNG's IHDR chunk. */
function pngSize(buf: Buffer): { width: number; height: number } {
  assert.ok(buf.subarray(0, 8).equals(PNG_SIGNATURE), "PNG signature");
  assert.equal(buf.toString("ascii", 12, 16), "IHDR");
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

describe("brand icons", () => {
  it("favicon.ico is a multi-size ICO (16/32/48/256), not the create-next-app default", () => {
    const ico = readFileSync("src/app/favicon.ico");
    assert.notEqual(ico.length, CREATE_NEXT_APP_FAVICON_BYTES);
    assert.equal(ico.readUInt16LE(0), 0, "reserved");
    assert.equal(ico.readUInt16LE(2), 1, "type 1 = icon");
    const count = ico.readUInt16LE(4);
    const sizes: number[] = [];
    for (let i = 0; i < count; i++) {
      const e = 6 + 16 * i;
      const width = ico.readUInt8(e) || 256;
      const height = ico.readUInt8(e + 1) || 256;
      const length = ico.readUInt32LE(e + 8);
      const offset = ico.readUInt32LE(e + 12);
      assert.ok(offset + length <= ico.length, `image ${i} lies inside the file`);
      const image = ico.subarray(offset, offset + length);
      // Each entry is stored as PNG; its IHDR must agree with the directory.
      assert.deepEqual(pngSize(image), { width, height });
      assert.equal(width, height);
      sizes.push(width);
    }
    assert.deepEqual(sizes.sort((a, b) => a - b), [16, 32, 48, 256]);
  });

  it("icon.png is a square 256x256 PNG", () => {
    assert.deepEqual(pngSize(readFileSync("src/app/icon.png")), { width: 256, height: 256 });
  });

  it("apple-icon.png is 180x180", () => {
    assert.deepEqual(pngSize(readFileSync("src/app/apple-icon.png")), { width: 180, height: 180 });
  });

  it("the brand mark the MCP serverInfo and server.json point at is a 512x512 PNG", () => {
    assert.deepEqual(pngSize(readFileSync("public/brand/launchpad-hq-512.png")), { width: 512, height: 512 });
  });
});
